function checkPlugin() {
    try {
        vnpt_plugin.checkPlugin().then(function (data) {
            if (data === "1") {
                toastr.error("Plugin đã sẵn sàng")
                clearTimeout(timer); // clear 
                vnpt_plugin.setLicenseKey(key).then(function (data) {
                    //	vnpt_plugin.checkPlugin().then(function (data) {
                    console.log(data);
                }).catch(function (e) {
                    console.log(e)
                });
            }
            else {
                toastr.error("VNPT-CA Plugin chưa được cài đặt hoặc chưa được bật");
                timer = setTimeout(checkPlugin, 1500);
            }
        }).catch(function (e) {
            toastr.error("VNPT-CA Plugin chưa được cài đặt hoặc chưa được bật");
        });
    } catch (e) {
        toastr.error("VNPT-CA Plugin chưa được cài đặt hoặc chưa được bật");
    };
}

