// chon file tren may
function chooseFile() {
    try {
        vnpt_plugin.checkPlugin().then(function (data) {
            if (data === "1") {
                vnpt_plugin.setLicenseKey(key).then(function (data) {
                    vnpt_plugin.chooseFile().then(function (data) {
                        if (data !== "") {
                            var jsOb = JSON.parse(data);
                            console.log(jsOb)
                            document.getElementById('filePath').value = jsOb.path;
                            document.getElementById('fileBase').value = jsOb.base64;
                        }
                    }).catch(function (e) {
                        toastr.error(e);
                    });
                }).catch(function (e) {
                    console.log(e);
                    toastr.error("VNPT-CA Plugin chưa được cài đặt hoặc chưa được bật");
                });
            }
            else {
                toastr.error("VNPT-CA Plugin chưa được cài đặt hoặc chưa được bật");
            }
        }).catch(function (e) {
            //toastr.error(e);
            toastr.error("VNPT-CA Plugin chưa được cài đặt hoặc chưa được bật");
        });
    }
    catch (e) {
        console.log(e);
    }
}

// sign
function SignAdvanced(data, type, option) {
    var dataJS = {};

    var arrData = [];
    // 1			
    dataJS.data = data;
    dataJS.type = type;
    dataJS.sigOptions = JSON.stringify(option);

    var jsData = "";
    jsData += JSON.stringify(dataJS);
    //
    arrData.push(jsData);
    var serial = "";
    serial = document.getElementById('serial').value;
    //var serial = "5401f8b96391ca0971053be87920ef25,5401010110e31850de43d42e6f53c531";

    vnpt_plugin.signArrDataAdvanced(arrData, serial, true).then(function (data) {
        showMessage(data);
    }).catch(function (e) {
        toastr.error(e);
    });
}

function showMessage(data) {
    if (typeof JSON.parse(data).code !== 'undefined') {
        var jsOb = JSON.parse(data);
    } else {
        var jsOb = JSON.parse(JSON.parse(data)[0]);
    }

    switch (jsOb.code) {
        case 0:
            err = "Ký thành công";
            toastr.error(err);
            //document.getElementById('output').value = jsOb.data;
            //var filename = document.getElementById('filePath').value.replace(/^.*[\\\/]/, '');
            //var fileExtension = filename.split('.').pop();
            //var name = filename.substring(0, filename.length - fileExtension.length - 1);
            //var mimeType = arrMappingMIMETypes[fileExtension];
            //download("{0};base64,{1}".format(mimeType, (jsOb.data)), name + "_signed", fileExtension, mimeType);
            break;
        case 1:
            err = "Dữ liệu đầu vào không đúng định dạng";
            break;
        case 2:
            err = "Không lấy được thông tin chứng thư số";
            break;
        case 3:
            err = "Có lỗi trong quá trình ký số";
            break;
        case 4:
            err = ("Chứng thư số không có khóa bí mật");
            break;
        case 5:
            err = ("Lỗi không xác định");
            break;
        case 6:
            err = ("Ký pdf: không tìm thấy tham số số trang cần ký");
            break;
        case 7:
            err = ("Ký pdf: trang đặt chữ ký không tồn tại");
            break;
        case 8:
            err = ("Ký xml: không tìm thấy thẻ ký số");
            break;
        case 9:
            err = ("Ký pdf: không tìm thấy id của thẻ ký số");
            break;
        case 10:
            err = ("Dữ liệu ký đã chứa một hoặc nhiều chữ ký không hợp lệ");
            break;
        case 11:
            err = ("Người dùng hủy bỏ");
            break;
        case 13:
            err = "Dữ liệu ký rỗng";
            break;
        default:
            err = ("Lỗi không xác định");
            break;
    }
    if (jsOb.code !== 0) {
        document.getElementById('output').value = err;
    }
}

function sign() {
    document.getElementById('output').value = "";
    var dataInput = document.getElementById('fileBase').value;
    if (dataInput.length === 0) {
        toastr.error("Chưa có dữ liệu ký");
        return;
    }
    var fileName = document.getElementById('filePath').value;
    var fileSplit = fileName.split(".");
    var fileExtension = fileSplit[fileSplit.length - 1].toLowerCase();
    if (fileExtension !== "xml" && fileExtension !== "pdf" && fileExtension !== "docx"
        && fileExtension !== "xlsx" && fileExtension !== "pptx" && fileExtension !== "txt") {
        toastr.error("Định dạng file chưa được hỗ trợ");
        return;
    }
    var sigOptions = new PdfSigner();

    sigOptions.llx = 346;
    sigOptions.lly = 235;
    sigOptions.urx = 546;
    sigOptions.ury = 335;
    sigOptions.page = 1;
    sigOptions.ImageBase64 = "";
    sigOptions.SigVisible = true;
    sigOptions.SigSignerVisible = true;
    sigOptions.SigEmailVisible = true;
    sigOptions.SigPositionVisible = true;
    sigOptions.SigSigningTimeVisible = true;
    sigOptions.AdvancedCustom = true; //=> Ký nâng cao

    sigOptions.ValidationOption = false;
    sigOptions.SigTextSize = 10;

    sigOptions.SetImageBackground = true;

    SignAdvanced(dataInput, fileExtension, sigOptions);
}

// Lay thong tin CTS co tren may KH
function GetCertInfo() {
    vnpt_plugin.getCertInfo().then(function (data) {
        if (data === "" || data === null) {
            toastr.error("Không lấy được thông tin chứng thư số");
            return;
        }
        var jsOb = JSON.parse(data);
        if (jsOb !== "" || jsOb != null) {
            if (jsOb.code == -1) {
                toastr.error(jsOb.error);
                return;
            }
            document.getElementById('serial').value = jsOb.serial;
            document.getElementById('base64Cert').value = jsOb.base64;
        }
    }).catch(function (e) {
        toastr.error(e);
    });
}

function CheckToken() {
    vnpt_plugin.CheckToken().then(function (data) {
        switch (Number(data)) {
            case 1:
                err = "Đã cắm USB Token";
                break;
            case 0:
                err = "Chưa cắm USB Token";
                break;
            case -1:
                err = "Có lỗi trong quá trình kiểm tra";
                break;
            default:
                err = "Lỗi không xác định";
                break;
        }
        toastr.error(err);
    }).catch(function (e) {
        toastr.error(e);
    });
}

function GetVersion() {
    vnpt_plugin.getVersion().then(function (data) {
        toastr.error("Plugin Version :" + data);
    }).catch(function (e) {
        toastr.error(e);
    });
}

function CheckBrowser() {
    if (vnpt_plugin.checkBrowser()) {
        toastr.error("Trình duyệt hiện tại có hỗ trợ Plugin");
    } else {
        toastr.error("Trình duyệt hiện tại không hỗ trợ Plugin");
    }
}

function ValidateCertificateBase64() {
    checkCRLorOCSP = false;
    var dateTime = null;
    var ocspUrl = null;
    var certBase64 = document.getElementById('base64Cert').value;
    if (certBase64 === null || certBase64.length === 0) {
        toastr.error("Nhập chuỗi base64 của chứng thư số");
        return;
    }
    vnpt_plugin.setLicenseKey(key).then(function (data) {
        vnpt_plugin.ValidateCertificateBase64(certBase64, dateTime, ocspUrl).then(function (data) {
            switch (Number(data)) {
                case 0:
                    err = "Chứng thư số hợp lệ";
                    break;
                case 1:
                    err = "Lỗi không xác định";
                    break;
                case 2:
                    err = "Chứng thư số hết hạn";
                    break;
                case 3:
                    err = "Chứng thư số chưa đến hạn";
                    break;
                case 4:
                    err = "Chứng thư số đã bị thu hồi";
                    break;
                case 5:
                    err = "Chứng thư số không có quyền ký dữ liệu";
                    break;
                case 6:
                    err = "Kiểm tra trạng thái thu hồi của chứng thư không thành công";
                    break;
                case 7:
                    err = "Chứng thư số không được cấp bới CA tin tưởng";
                    break;
                case 8:
                    err = "Không lấy được thông tin chứng thư số";
                    break;
                case 9:
                    err = "Không lấy được thông tin chứng thư số CA";
                    break;
                case 10:
                    err = "Không lấy được thông tin chứng thư số CA";
                    break;
                default:
                    err = "Lỗi không xác định";
                    break;
            }
            toastr.error(err);
        }).catch(function (e) {
            toastr.error(e);
        });
    }).catch(function (e) {
        toastr.error(e);
    });
}